import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CFOYCmPM.js";const r="/dayz-studio/manual/images/dayz_studio_npcs_view.png",p=JSON.parse('{"title":"Chapter 4: NPC Creation & Autonomous Behaviour Graphs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/npc-behaviour.md","filePath":"guide/npc-behaviour.md","lastUpdated":null}'),n={name:"guide/npc-behaviour.md"};function s(l,e,d,h,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="chapter-4-npc-creation-autonomous-behaviour-graphs" tabindex="-1">Chapter 4: NPC Creation &amp; Autonomous Behaviour Graphs <a class="header-anchor" href="#chapter-4-npc-creation-autonomous-behaviour-graphs" aria-label="Permalink to &quot;Chapter 4: NPC Creation &amp; Autonomous Behaviour Graphs&quot;">​</a></h1><p>In DayZ Studio, NPCs (Non-Player Characters) are not static mannequins. They are living characters with customizable survivor models, clothing, weapons, daily schedules, and autonomous AI brains.</p><hr><h2 id="👤-the-npcs-tab-alt-5" tabindex="-1">👤 The NPCs Tab (<code>Alt + 5</code>) <a class="header-anchor" href="#👤-the-npcs-tab-alt-5" aria-label="Permalink to &quot;👤 The NPCs Tab (`Alt + 5`)&quot;">​</a></h2><p><img src="'+r+'" alt="DayZ Studio NPC Behaviour Editor"></p><h3 id="_1-dressing-equipping-your-character" tabindex="-1">1. Dressing &amp; Equipping Your Character <a class="header-anchor" href="#_1-dressing-equipping-your-character" aria-label="Permalink to &quot;1. Dressing &amp; Equipping Your Character&quot;">​</a></h3><ul><li><strong>31 Survivor Models:</strong> Choose from diverse male and female characters.</li><li><strong>13 Outfit Presets:</strong> Instant gear presets including <em>Survivor</em>, <em>Hunter</em>, <em>Soldier</em>, <em>Police Officer</em>, <em>Bandit</em>, and <em>Hazmat</em>.</li><li><strong>Custom Equipment:</strong> Equip individual hats, vests, plate carriers, backpacks, gloves, boots, and slung firearms.</li><li><strong>Independent Characters:</strong> Quests pick NPCs from this tab. A single character can be involved in multiple quests or simply wander the camp as an ambient survivor.</li></ul><hr><h2 id="🧠-the-behaviour-node-architecture" tabindex="-1">🧠 The Behaviour Node Architecture <a class="header-anchor" href="#🧠-the-behaviour-node-architecture" aria-label="Permalink to &quot;🧠 The Behaviour Node Architecture&quot;">​</a></h2><p>NPC logic is built using a clean, visual node flowchart:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Node Type</th><th style="text-align:left;">Function</th><th style="text-align:left;">Examples</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Events (Green)</strong></td><td style="text-align:left;">Triggers that kick off a chain of actions.</td><td style="text-align:left;"><em>Spawned</em>, <em>Player comes near (3m)</em>, <em>Talked to</em>, <em>Hostile player seen</em>, <em>Time of day</em>.</td></tr><tr><td style="text-align:left;"><strong>Activities (Blue)</strong></td><td style="text-align:left;">Looping behaviors that run until something interrupts them.</td><td style="text-align:left;"><em>Patrol</em>, <em>Wander in radius</em>, <em>Stand at point</em>, <em>Guard location</em>, <em>Follow player</em>.</td></tr><tr><td style="text-align:left;"><strong>Steps (Yellow)</strong></td><td style="text-align:left;">Sequential actions executed in chronological order.</td><td style="text-align:left;"><em>Face player</em>, <em>Say text overhead</em>, <em>Play emote</em>, <em>Give item</em>, <em>Wait</em>.</td></tr><tr><td style="text-align:left;"><strong>Flow (Gray)</strong></td><td style="text-align:left;">Conditional branch logic.</td><td style="text-align:left;"><em>Only if</em>, <em>Random chance</em>.</td></tr></tbody></table><hr><h2 id="🚶-step-by-step-tutorial-creating-a-guard-with-a-day-night-routine" tabindex="-1">🚶 Step-by-Step Tutorial: Creating a Guard with a Day/Night Routine <a class="header-anchor" href="#🚶-step-by-step-tutorial-creating-a-guard-with-a-day-night-routine" aria-label="Permalink to &quot;🚶 Step-by-Step Tutorial: Creating a Guard with a Day/Night Routine&quot;">​</a></h2><p>Let&#39;s build a camp sentry who patrols the perimeter during the daytime, warms his hands by the campfire at night, and greets approaching players:</p><h3 id="step-1-create-the-npc" tabindex="-1">Step 1: Create the NPC <a class="header-anchor" href="#step-1-create-the-npc" aria-label="Permalink to &quot;Step 1: Create the NPC&quot;">​</a></h3><ol><li>Switch to the <strong>NPCs Tab</strong> (<code>Alt + 5</code>).</li><li>Click <strong>+ New NPC</strong> and name him <code>Guard_Alexei</code>.</li><li>Select the <strong>Soldier</strong> outfit preset and equip an AK-74 on his shoulder.</li></ol><h3 id="step-2-configure-the-daytime-patrol" tabindex="-1">Step 2: Configure the Daytime Patrol <a class="header-anchor" href="#step-2-configure-the-daytime-patrol" aria-label="Permalink to &quot;Step 2: Configure the Daytime Patrol&quot;">​</a></h3><ol><li>Right-click the behavior canvas and add a <strong>Time of Day</strong> event node.</li><li>Set time to <code>06:00</code> (Morning).</li><li>Connect the event to a <strong>Patrol</strong> activity node.</li><li>Click <strong>+ Draw patrol route</strong> on the map, then click 4 waypoints around your outpost walls.</li></ol><h3 id="step-3-configure-the-nighttime-routine" tabindex="-1">Step 3: Configure the Nighttime Routine <a class="header-anchor" href="#step-3-configure-the-nighttime-routine" aria-label="Permalink to &quot;Step 3: Configure the Nighttime Routine&quot;">​</a></h3><ol><li>Add a second <strong>Time of Day</strong> event node set to <code>20:00</code> (Night).</li><li>Connect it to a <strong>Stand At</strong> activity node positioned beside your campfire.</li><li>In the Inspector, set his animation state to <code>Sit by fire (warming hands)</code>.</li></ol><h3 id="step-4-add-reactive-player-interactions" tabindex="-1">Step 4: Add Reactive Player Interactions <a class="header-anchor" href="#step-4-add-reactive-player-interactions" aria-label="Permalink to &quot;Step 4: Add Reactive Player Interactions&quot;">​</a></h3><ol><li>Add a <strong>Player Comes Near</strong> event node (radius: <code>3 meters</code>).</li><li>Connect to <strong>Face Player</strong>.</li><li>Connect to <strong>Emote: Wave</strong>.</li><li>Connect to <strong>Say</strong>: <em>&quot;Keep your weapon holstered while inside the camp.&quot;</em></li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Always Talkable:</strong> If a player talks to Alexei while he is walking his patrol, he will smoothly pause, turn to face the player, finish the conversation or trade, and automatically resume his patrol when the player walks away!</p></div><hr><h2 id="🎭-in-game-gestures-emotes" tabindex="-1">🎭 In-Game Gestures &amp; Emotes <a class="header-anchor" href="#🎭-in-game-gestures-emotes" aria-label="Permalink to &quot;🎭 In-Game Gestures &amp; Emotes&quot;">​</a></h2><p>DayZ Studio supports 19 built-in animations for NPCs:</p><ul><li><code>Wave</code>, <code>Point</code>, <code>Salute</code>, <code>Come here</code>, <code>Nod</code>, <code>Clap</code>, <code>Shrug</code>, <code>Sit</code>, <code>Sit by the fire</code>, <code>Dance</code>, and more.</li><li>Characters dynamically transition out of seated postures before performing gestures.</li></ul>',27)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
